function cellInfo = bus_pglfd(varargin)
% BUS_PGLFD returns a cell array containing bus object information
%
% Optional Input: 'false' will suppress a call to Simulink.Bus.cellToObject
%                 when the MATLAB file is executed.
% The order of bus element attributes is as follows:
%   ElementName, Dimensions, DataType, SampleTime, Complexity, SamplingMode, DimensionsMode, Min, Max, DocUnits, Description

suppressObject = false;
if nargin == 1 && islogical(varargin{1}) && varargin{1} == false
    suppressObject = true;
elseif nargin > 1
    error('Invalid input argument(s) encountered');
end

cellInfo = { ...
    { ...
    'bus_manifold_passivity_computed', ...
    '', ...
    '', ...
    'Auto', ...
    '-1', { ...
    {'delta_x', 6, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'delta_v', 6, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'p_damping', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'e_initial', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'method', 1, 'uint8', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    } ...
    } ...
    { ...
    'bus_manifold_passivity_curl', ...
    '', ...
    '', ...
    'Auto', ...
    '-1', { ...
    {'allow_asymmetric', 1, 'boolean', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'p_active', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'d', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    } ...
    } ...
    { ...
    'bus_manifold_passivity_damping', ...
    '', ...
    '', ...
    'Auto', ...
    '-1', { ...
    {'d', [6 6], 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'delta_v', 6, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'p_damping', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    } ...
    } ...
    { ...
    'bus_manifold_passivity_desired', ...
    '', ...
    '', ...
    'Auto', ...
    '-1', { ...
    {'k', [6 6], 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'d', [6 6], 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    } ...
    } ...
    { ...
    'bus_manifold_passivity_info', ...
    '', ...
    '', ...
    'Auto', ...
    '-1', { ...
    {'desired', 1, 'Bus: bus_manifold_passivity_desired', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'computed', 1, 'Bus: bus_manifold_passivity_computed', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'none', 1, 'Bus: bus_manifold_passivity_none', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'k', 1, 'Bus: bus_manifold_passivity_k', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'l', 1, 'Bus: bus_manifold_passivity_l', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'l_disc', 1, 'bus_manifold_passivity_l_discrete', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'curl', 1, 'Bus: bus_manifold_passivity_curl', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    } ...
    } ...
    { ...
    'bus_manifold_passivity_k', ...
    '', ...
    '', ...
    'Auto', ...
    '-1', { ...
    {'reset', 1, 'boolean', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'d', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'k', [6 6], 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'p_active', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'spring_energy', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    } ...
    } ...
    { ...
    'bus_manifold_passivity_l', ...
    '', ...
    '', ...
    'Auto', ...
    '-1', { ...
    {'reset', 1, 'boolean', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'d', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'ddot', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'p_active', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'spring_energy', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    } ...
    } ...
    { ...
    'bus_manifold_passivity_l_discrete', ...
    '', ...
    '', ...
    'Auto', ...
    '-1', { ...
    {'reset', 1, 'boolean', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'d', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'p_active', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'spring_energy', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    } ...
    } ...
    { ...
    'bus_manifold_passivity_none', ...
    '', ...
    '', ...
    'Auto', ...
    '-1', { ...
    {'p_active', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    {'spring_energy', 1, 'double', -1, 'real', 'Sample', 'Fixed', [], [], '', ''}; ...
    } ...
    } ...
    
    }';

if ~suppressObject
    % Create bus objects in the MATLAB base workspace
    Simulink.Bus.cellToObject(cellInfo)
end
